    function setUp() public {

        target = Honey(payable(TARGET));
        owner = target.owner();
        router = target.router();
        pair = target.pair();

        // Give attacker and owner ETH for gas/liquidity
        deal(attacker, 100 ether);
        deal(owner, 10 ether);

